	var options = {
		type: "iframePopup",
		id: "popup_exam1",
		width: "500px",
		height: "400px",
		top: 100,
		left: 50,
		popupName: "popup_exam1",
		dataObject: {
			type: "json",
			data: {
				"type": "iframePopup"
			},
			name: "exam_param"
		}
	};
	$p.openPopup("/sample/common_link/p_iframePopup_isPopup_WESE-447_(WSQ-5371)_main_popup1.xml", options);
};
